import{_ as o,o as d,c as t,a6 as c}from"./chunks/framework.BrkgobfX.js";const m=JSON.parse('{"title":"自定义与扩展","description":"CLAUDE.md、技能（skills）、插件、MCP、Hooks 与界面自定义","frontmatter":{"title":"自定义与扩展","description":"CLAUDE.md、技能（skills）、插件、MCP、Hooks 与界面自定义","source":"https://daiw.org/manual/claude-code/commands-customization"},"headers":[],"relativePath":"manual/agent/claude-code/commands-customization.md","filePath":"manual/agent/claude-code/commands-customization.md"}'),a={name:"manual/agent/claude-code/commands-customization.md"};function l(r,e,n,s,i,h){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="自定义与扩展" tabindex="-1">自定义与扩展 <a class="header-anchor" href="#自定义与扩展" aria-label="Permalink to &quot;自定义与扩展&quot;">​</a></h1><blockquote><p>CLAUDE.md、技能（skills）、插件、MCP、Hooks 与界面自定义</p></blockquote><h2 id="项目记忆-claude-md" tabindex="-1">项目记忆：CLAUDE.md <a class="header-anchor" href="#项目记忆-claude-md" aria-label="Permalink to &quot;项目记忆：CLAUDE.md&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/init</code></td><td>探索项目并生成一份 <code>CLAUDE.md</code>。设置 <code>CLAUDE_CODE_NEW_INIT=1</code> 后会先交互式询问要生成哪些文件（CLAUDE.md、skills、hooks），再动手</td></tr><tr><td><code>/memory</code></td><td>编辑 <code>CLAUDE.md</code> 记忆文件，开关自动记忆（auto-memory），查看自动记忆已经记了什么</td></tr></tbody></table><p>一个新仓库的标准起手式是 <code>/init</code> 生成初版 <code>CLAUDE.md</code>，再用 <code>/memory</code> 逐步精修——把项目约定、常用命令、代码风格写成 Claude 每次都会看到的“常识”，而不是每次对话重复口述。<code>CLAUDE.md</code> 的存放位置、加载顺序、<code>@</code> 导入语法等文件层面的细节见<a href="/Front2Full/manual/agent/claude-code/configuration-files">配置文件</a>。</p><h2 id="技能-skills" tabindex="-1">技能（Skills） <a class="header-anchor" href="#技能-skills" aria-label="Permalink to &quot;技能（Skills）&quot;">​</a></h2><p>技能是“你反复复制粘贴的一段指令/清单/多步骤流程”的固化产物：写一个 <code>SKILL.md</code>，Claude 就能在合适时机自动使用，或者你用 <code>/skill-name</code> 直接调用。旧版的 <code>.claude/commands/*.md</code> 自定义命令已经并入技能体系，写法兼容，行为等价。完整说明见 <strong><a href="/Front2Full/manual/agent/claude-code/skills">Skills</a></strong> 与 <strong><a href="/Front2Full/manual/agent/claude-code/custom-commands">Commands</a></strong>。</p><h2 id="mcp-model-context-protocol" tabindex="-1">MCP(Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP(Model Context Protocol)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/mcp [reconnect &lt;server&gt;|enable|disable [&lt;server&gt;|all]]</code></td><td>管理 MCP 服务器连接与 OAuth 登录状态；不带参数打开交互列表。v2.1.273 起服务器在会话中途断开、自动重连也放弃时，会弹出指向这里的通知；v2.1.283 起工具列表一次显示更多工具，支持翻页键与鼠标，组织封禁的工具带告警图标</td></tr></tbody></table><p>命令行侧对应 <code>claude mcp</code>（增删配置）、<code>claude mcp login/logout &lt;server&gt;</code>（单独走 OAuth，v2.1.186+）。MCP 服务器暴露的 prompt 会以 <code>/mcp__&lt;server&gt;__&lt;prompt&gt;</code> 的形式出现在命令列表里。</p><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/plugin [subcommand]</code></td><td>管理插件；不带参数打开插件菜单，或直接传 <code>list</code>/<code>install</code>/<code>enable</code>/<code>disable</code>。🆕 v2.1.275 起 <code>/plugin install &lt;plugin&gt; --marketplace &lt;source&gt;</code> 会先提议添加该 marketplace，再安装插件</td></tr><tr><td><code>/reload-plugins [--force]</code></td><td>重新加载全部已启用插件，应用未生效的变更；如果会改变已加载的 MCP 工具集（从而让 prompt 缓存失效），需要加 <code>--force</code> 才会真正执行。v2.1.268 起用 <code>/plugin</code> 安装、启用、禁用的改动在关闭菜单时即生效，这一步只在手改插件文件后才需要</td></tr><tr><td><code>/reload-skills</code></td><td>重新扫描技能/命令目录，让磁盘上新增或修改的技能无需重启即可生效（v2.1.152+）。⚠️ v2.1.299 / v2.1.304 起自动压缩完成后会自动把技能列表重发给 Claude，而平时运行 <code>/reload-skills</code> 只补发新增或修改过的技能</td></tr></tbody></table><p>插件可以打包技能、subagent、hooks、MCP 服务器、输出风格，统一分发给团队；完整的组成、目录结构、Marketplace 与作者侧打包见 <strong><a href="/Front2Full/manual/agent/claude-code/plugins">Plugins</a></strong>。安装示例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin install skill-creator@claude-plugins-official</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/hooks</code></td><td>查看当前生效的 hook 配置（按工具事件分类）</td></tr></tbody></table><p>Hooks 用于在特定生命周期事件（如 <code>SessionStart</code>、<code>PreToolUse</code>、<code>Stop</code>）上运行确定性的脚本逻辑，弥补“技能只能靠模型自觉遵守指令”的不足，适合强制校验、审计、自动格式化等场景。v2.1.251 新增 <code>PreModelSwitch</code> / <code>PostModelSwitch</code> 事件，可以拦截、确认或注释一次模型切换。v2.1.271 起 SessionStart、UserPromptSubmit、PreToolUse、SessionEnd hook 运行时 spinner 会显示出来并计时，等待 SessionStart hook 的提示可以按 Esc 取消。</p><p>⚠️ v2.1.280 起 <code>PermissionRequest</code> 事件上不再运行 agent 型 hook（它的回答本来就无法批准或拒绝请求），会报错并指向 command 或 http hook。v2.1.281 起阻断型事件（如 PreToolUse）上的 <code>mcp_tool</code> hook 在 MCP 服务器还在连接时会等它连上（最长到 MCP 连接超时），不再被跳过；<code>/hooks</code> 的详情页也会说明这是哪种 hook、该到哪里修改，而不是一律指向 settings.json。🆕 v2.1.295 起 <code>command</code> 与 <code>http</code> hook（以及 v2.1.317 起 Agent SDK 的 hook 回调）支持 <code>onFailure: &quot;block&quot;</code>：无法启动、超时或返回非预期退出码时阻断操作而非放行。⚠️ v2.1.299 起 <code>UserPromptSubmit</code> hook 改在技能或自定义命令展开前运行，阻断提示词即可一并阻止内嵌的 <code>!</code> 命令；v2.1.300 起 <code>PreToolUse</code> 与 <code>PermissionRequest</code> 返回的 <code>updatedInput</code> 会按工具 schema 校验（剔除未知键，参数不合法则拒绝调用）；v2.1.302 / v2.1.312 起单会话同时运行的 <code>prompt</code> 与 <code>agent</code> hook 上限为 24 个（单事件最多 12 个）。</p><h2 id="界面与体验" tabindex="-1">界面与体验 <a class="header-anchor" href="#界面与体验" aria-label="Permalink to &quot;界面与体验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/theme</code></td><td>切换配色主题，含跟随终端明暗的 <code>auto</code>、色盲友好主题、ANSI 主题，以及 <code>~/.claude/themes/</code> 自定义主题</td></tr><tr><td><code>/statusline</code></td><td>配置状态栏；描述你想要的效果，或不带参数从当前 shell prompt 自动生成</td></tr><tr><td><code>/keybindings</code></td><td>打开快捷键配置文件。⚠️ v2.1.280 起 <code>y</code> / <code>n</code> 不再默认绑定对话框的确认 / 取消（统一用 Enter / Esc），想找回就在 <code>keybindings.json</code> 里把它们绑到 <code>confirm:yes</code> / <code>confirm:no</code>；v2.1.283 起拼错的修饰键（如 <code>ctl+k</code>）会在调试日志里告警，<code>/rewind</code> 与 <code>/diff</code> 的列表改用通用的 <code>select:*</code> 动作（旧的 <code>messageSelector:*</code> / <code>diff:*</code> 绑定仍然有效）</td></tr><tr><td><code>/color [color|default]</code></td><td>设置当前会话 prompt bar 颜色，连接 Remote Control 时会同步到 claude.ai/code</td></tr><tr><td><code>/focus</code></td><td>切换聚焦视图：只显示最后一条 prompt、一行工具调用摘要与最终回复</td></tr><tr><td><code>/output-style [name]</code></td><td>🆕 <strong>v2.1.269+</strong>：列出并切换输出风格（含 v2.1.237 起内置的「Concise」：先给结果、省掉铺垫），Remote Control 与无头会话里也能用</td></tr><tr><td><code>/tui [default|fullscreen]</code></td><td>设置终端 UI 渲染模式并重新进入（<code>fullscreen</code> 为无闪烁 alt-screen 渲染器）</td></tr></tbody></table><h2 id="项目专属能力" tabindex="-1">项目专属能力 <a class="header-anchor" href="#项目专属能力" aria-label="Permalink to &quot;项目专属能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/run</code></td><td>技能。启动并驱动你的应用，用真实运行效果而非只靠测试来验证改动（v2.1.145+）</td></tr><tr><td><code>/verify</code></td><td>技能。构建并运行项目，用观察到的实际行为确认一次代码改动是否达到预期（v2.1.145+）</td></tr><tr><td><code>/run-skill-generator</code></td><td>技能。从一次干净环境的启动过程中，记录安装命令、环境变量、启动脚本，固化成项目专属技能 <code>.claude/skills/run-&lt;project&gt;/</code>，供 <code>/run</code>、<code>/verify</code> 及其它 agent 复用（每个项目建议跑一次）</td></tr><tr><td><code>/dataviz [request]</code></td><td>技能。图表/仪表盘设计指导：自动挑选图表形式、按角色分配颜色、校验色盲友好度与对比度（v2.1.198+）</td></tr><tr><td><code>/claude-api [migrate|upgrade|cost-optimize|managed-agents-onboard|managed-agents-secure|api-version]</code></td><td>技能。加载 Claude API 参考资料（按项目语言自动匹配），或帮你把已有 Claude API 代码升级到新模型。v2.1.239 起 <code>upgrade</code> 把 Python 项目从 <code>anthropic</code> 0.x 迁到 1.x；v2.1.247 起 <code>cost-optimize</code> 分析现有项目的 API 花费，逐项做可测量的降本改动；🆕 v2.1.304 起 <code>managed-agents-secure</code> 对照官方安全指南检查 Managed Agents 设置；v2.1.307 起 <code>api-version</code> 将代码迁移至 API 版本 <code>2026-10-21</code>；v2.1.318 起 <code>managed-agents-onboard</code> 默认给新建 agent 的内置工具与模板 MCP 工具设置 <code>auto</code> 权限策略</td></tr><tr><td><code>/design-sync [hint]</code></td><td>技能。把仓库里的 React 设计系统同步上传到 Claude Design，让生成的设计使用你的真实组件（仅 Anthropic API 可用；⚠️ v2.1.302 起提示独立版 <code>claude.ai/design</code> 将于 2026-12-14 下线，v2.1.317 起设计系统已迁入 Claude 时会提前告知并停止）</td></tr><tr><td><code>/design-sync [hint]</code></td><td>技能。把仓库里的 React 设计系统同步上传到 Claude Design，让生成的设计使用你的真实组件（仅 Anthropic API 可用；⚠️ v2.1.302 起提示独立版 <code>claude.ai/design</code> 将于 2026-12-14 下线，v2.1.317 起设计系统已迁入 Claude 时会提前告知并停止）</td></tr><tr><td><code>/design-login</code></td><td>为 <code>/design-sync</code> 授权 claude.ai 账号访问设计系统</td></tr></tbody></table><h2 id="建议的自定义投入顺序" tabindex="-1">建议的自定义投入顺序 <a class="header-anchor" href="#建议的自定义投入顺序" aria-label="Permalink to &quot;建议的自定义投入顺序&quot;">​</a></h2><ol><li>先写好 <code>CLAUDE.md</code>(<code>/init</code> + <code>/memory</code>），这是成本最低、收益最直接的一步。</li><li>把“经常口述的多步骤指令”沉淀成个人/项目技能。</li><li>需要跨项目共享或团队统一分发时，再打包成插件。</li><li>需要“确定性强制执行”（而不是靠模型自觉）时，才引入 hooks。</li></ol>',24)])])}const p=o(a,[["render",l]]);export{m as __pageData,p as default};
